namespace OpenTPW;

/// <summary>
/// Register of the original-save import mappings that are not traced (docs/reverse/SAVE-plan.md §8.2,
/// docs/SAVE-CONTAINER.md, "Import into OpenTPW"). Each entry has a matching <c>// [APPROX:SAVE-NNN]</c>
/// comment at its code site. Values the import drops are also reported in <see cref="OriginalEconomyImport.Evidence"/>.
/// </summary>
public static class SaveApproximations
{
	public static readonly IReadOnlyList<(string Id, string Assumption, string EvidenceNeeded)> All = new[]
	{
		("SAVE-001", "the save's world generator word (mRandomSeed) is reported but not imported. It is the whole state of the original's one shared world LCG (tp.exe 0x516330 on world +0x1DA708: s = s × 0x19660D + 0x3C6EF35F, rotated right by 13, absolute value returned), written raw by the world saver (0x51710E) and read back raw by the loader (0x517DE7); a new park seeds it from time() (0x515879). OpenTPW's economy, guest and script streams are separate generators derived from the world seed, so restoring the word alone would reproduce no draw", "DET-I2 port of the world LCG with the original's call order (DET-005, DET-013), then restoring this word"),
		("SAVE-002", "the saved guests (model 1) are not imported; OpenTPW's guest simulation starts with its own arrivals", "decoded person/guest fields and an OpenTPW guest save target"),
		("SAVE-003", "saved staff are imported with the display state of their saved state word but no job (the word's target, ride, toilet or rest area is not restored), their inline name replaced by name index 0, their hire time stamp rounded down to its park turn and no patrol region, rest area, idle tick or jobs-done count", "the units of the patrol corners +0x20a/+0x20c and whether a saved rest-area id names the reloaded object"),
		("SAVE-004", "the pool's sub-type and on-pointer bytes, its people-in-category counts, stop-producing flags and opening-pool flag are not imported: OpenTPW keeps no staff sub-type, the placement in hand is not saved, and the counts and flags are not traced", "the readers of mPeopleInCat and mStopProducing"),
		("SAVE-005", "the challenge slots' loss counts, the follow-up's carried object and the day an unanswered offer was made are not imported, and the first offer does not wait for an open park", "what reads the loss counts and how the follow-up types read the carried object"),
		("SAVE-006", "an attraction's saved state enum, chance of winning, third gauge, histories, totals, name lines, operating capacity, duration and speed, quality of goods, queue size, walk-away counts and mesh instance ID are not imported (the customer count is taken as the use word +412 and the time stamp as the build time +20, unverified) (open/broken state comes from its script, the queue from the laid queue cells). In tp.exe a saved state 1 (broken down), 2 (upgrading) or 4 (condemned) persists, because the per-update dispatch 0x4E0E00 re-derives only state 0 from the script (0x4E14E0), and the saved win byte +0x190 is 100 minus the type's losing chance at construction (0x4DB39A), won when R % 100 is at most the byte (0x4E26E2)", "readers of the histories and operating fields, any post-load pass over the state word, and OpenTPW counterparts of the count fields"),
		("SAVE-007", "lab projects OpenTPW does not list are dropped, a saved current project OpenTPW would not research now is not selected, the save's highest open group is recomputed, and the object table's researched flags are not read", "the object table's researched flags (+0x10, outside the lab block)"),
		("SAVE-008", "the batch balance and the loan offers' Available flags are not imported (OpenTPW offers every offer not taken). In tp.exe the batch word +0x10 is a pending credit that the bank's month message adds to the balance, the money-in total and the year's profit and then zeroes (0x4D0393..0x4D03DB), and the constructor marks an offer Available when its amount is at most 10,000 (0x4CF84B). The ledger month opens at the current balance; the bank keeps no month-opening word, mLastBalance being the balance after the last debit, instalment or payoff (0x4D0228, 0x4D08E1)", "the writer of the offers' Available flags after construction and the offer list that reads them; a save with a non-zero batch word"),
		("SAVE-009", "the force-strike word, the picked-up staff id and the trained byte of the staff HQ are not imported: OpenTPW keeps no forced strike, held-staff id or trained flag", "where the force-strike word is set and cleared"),
		("SAVE-010", "the opaque blocks (scripts, particles, messages, clock words, cadence, track/flying rides, RSSE, camera, advisor presentation, sound, cheats, advisor scoring, UI) and the Coasters block, whose structure SaveCoasterBlock now reads (SAVE-920 to SAVE-923) without importing any state, the weather, park analyser, tag system, mechanic HQ and UI message receiver things, the world state, arrival variables and arrival bytes, the calendar session start and the advisor controller's time signature, sound, three raw words, current record, mRequestedLastTutorial and mMessagePlaying are not imported, nor are its pending advice and history when no automatic advisor is attached; of the cell map only path cells, occupancy, MAP attributes and each path cell's texture and turn are read, and a saved path tile is drawn only while the cell's path neighbours equal the saved ones and its turn is 0/90/180/270 (otherwise the tile is chosen from the neighbours); object scripts restart from their archives, where the original's RSSE loader (tp.exe 0x5597A0: header RSSE, then per script its 0xF4-byte record and saved buffers, then its OBJ list) restores every script's saved state", "decoded block layouts and the original's post-load reconstruction"),
		("SAVE-011", "the delimiters of blocks whose width is not traced are located by their bytes: a payload that splits into its blocks in more than one way, or holds a delimiter's bytes more than MaximumDelimiterOccurrences times, is rejected, while the original loader (tp.exe 0x415270) runs each block's own reader and then compares the next 4 bytes with the block's tag (WRLD at 0x415371), failing on a mismatch, so it never searches and loads such payloads", "the serialized widths of the remaining blocks (their PC readers: message centre 0x40FD60, game system 0x5506E0, ride system 0x4647A0, track rides 0x543560, flying rides 0x55E020, RSSE 0x5597A0, camera 0x42CEC0, coasters 0x437B60, advisor 0x599D00, sound 0x51C400)"),
		("SAVE-920", "a Coasters block (the body between the stored EMAK and SAOC delimiters) that lists more than one coaster is refused: the original's loader (tp.exe 0x437B60) reads every coaster in turn, and each coaster's train payload holds one 27-byte record per train slot of its type (the type's +0x2E8 count, 0x438386) and per car an 11-byte record followed by its two counted u32 lists, so its extent needs the coaster type's train and car counts, which this Files-layer reader does not have", "the coaster type's train slot and car counts passed to the reader (type +0x2E8 and the car list count); a nonempty original Coasters block"),
		("SAVE-921", "the coaster header and section flag words are remapped controller and node flags; they are kept raw and no bit is interpreted. The section map is traced in tp.exe: the saver (0x437615..0x4376E0) writes memory bits 0x1/0x2/0x4/0x80/0x40/0x100/0x10000/0x20000/0x40000/0x80000/0x200000/0x400000 as wire 0x1/0x2/0x4/0x8/0x10/0x20/0x40/0x80/0x100/0x200/0x400/0x800, and the loader (0x437EA6..0x437F58) sets 0x1/0x2/0x4, 0x10000, 0x20000, 0x40000, 0x80000, 0x200000 and 0x400000 back but not 0x80, 0x40 or 0x100", "the meaning of the remapped bits and of wire 0x8/0x10/0x20 on load; the header word's map at instruction level"),
		("SAVE-922", "the coaster header's controller words (+8, +12, +16, +20, +28, +32, +244, +240), the block's three globals, the auxiliary ordinals' meaning, the word section+112 and the section floats +220/+224/+248 are saved but their meaning is not traced; they are reported raw (+248 matches the loop-rotate slider's node +248 by offset only). Traced in tp.exe's loader 0x437B60: the controller word +16 is matched against the live coasters' +0x10 to bind the block to an existing coaster (0x437CBF; none matching dereferences null, 0x437CD5), the three globals are the coaster slot allocator's state (0x790B04, 0x790B00, 0x791CE0, passed to 0x468760, whose slot is stored in the controller's +0x14) and +240 is restored to the controller's +0xF0 (0x438373), which 0x43BA90 copies to the room capacity +0xB8 (0x43BBD1)", "the readers of the controller words +8, +12, +28, +32 and +244 and of the section words in the original coaster module"),
		("SAVE-923", "the train/car/passenger payload that follows each coaster's sections is not decoded; it is preserved as raw bytes and never interpreted, and no original coaster chunk is written. Its layout is traced in tp.exe (saver 0x437300, loader 0x437B60): per train slot a 27-byte record (u32 flags, u8 train +0xC, u32 train +0x74, +0x78, +0x38, +0x64, +0x68, u16 train +0x10; 0x43783B), then per car an 11-byte record (u32 flags, u8 counts A and B from car +0x30/+0x34, u8 car +0x44, u32 car +0xC; 0x4378A5) and A then B u32 entries from the car's lists +0x28/+0x2C", "the meanings of the train and car words; the bytes of a nonempty original Coasters block"),
			};
}
